// No CMS in this shop (scaffolded with --cms=none), so lib/cms is absent —
// `isHomeSlug` is inlined here. Slugs that resolve to the site home page,
// which is always served at `/`.
const HOME_SLUGS = ['home', 'home-personalized', 'index', 'home-generic'];

/** True when a slug (with or without a leading slash) refers to the home page. */
function isHomeSlug(slug: string): boolean {
  const normalized = slug.replace(/^\/+/, '').toLowerCase();
  return normalized === '' || HOME_SLUGS.includes(normalized);
}
